+        final AtomicReference<UpdateResponse> updateResponse = new AtomicReference<>();
+        resumableUploads.compute(uploadId, (uid, existing) -> {
+            if (existing == null) {
+                throw failAndThrow("Attempted to update a non-existent resumable: " + uid);
+            }
